-- =============================================================================
-- ESQUEMA DE MEDIAGENDA PARA POSTGRESQL (SUPABASE)
--
-- Solo estructura, sin datos. Crea las tablas en el esquema activo (search_path).
-- En Supabase se aplica después de database/supabase_setup.sql, que crea el
-- esquema "mediagenda" y el usuario de la aplicación.
--
-- Equivalencias con la versión de MySQL (schema_mysql.sql):
--   - ENUM            -> VARCHAR con restricción CHECK.
--   - TINYINT(1)      -> SMALLINT (el código compara con 0 y 1).
--   - AUTO_INCREMENT  -> GENERATED BY DEFAULT AS IDENTITY.
--   - slot_activo     -> índice único parcial (WHERE estado_cita <> 'Cancelada'):
--                        impide dos citas activas del mismo médico a la misma hora.
-- =============================================================================

CREATE TABLE especialidades (
    id_especialidad     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_especialidad VARCHAR(100) NOT NULL
);

CREATE TABLE consultorios (
    id_consultorio  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre          VARCHAR(100) NOT NULL,
    id_especialidad INTEGER REFERENCES especialidades (id_especialidad),
    ubicacion       VARCHAR(255) NOT NULL
);

CREATE TABLE doctores (
    id_doctor        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre           VARCHAR(50) NOT NULL,
    apellido_paterno VARCHAR(50) NOT NULL,
    id_especialidad  INTEGER NOT NULL REFERENCES especialidades (id_especialidad) ON DELETE CASCADE,
    id_consultorio   INTEGER REFERENCES consultorios (id_consultorio) ON DELETE SET NULL,
    estado           VARCHAR(10) NOT NULL DEFAULT 'Activo' CHECK (estado IN ('Activo', 'Inactivo'))
);
CREATE INDEX idx_doctores_consultorio ON doctores (id_consultorio);

CREATE TABLE enfermeros (
    id_enfermero     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre           VARCHAR(50) NOT NULL,
    apellido_paterno VARCHAR(50) NOT NULL,
    turno            VARCHAR(10) NOT NULL CHECK (turno IN ('Matutino', 'Vespertino', 'Nocturno')),
    id_consultorio   INTEGER REFERENCES consultorios (id_consultorio) ON DELETE SET NULL
);

CREATE TABLE pacientes (
    id_paciente            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    nombre                 VARCHAR(50) NOT NULL,
    apellido_paterno       VARCHAR(50) NOT NULL,
    apellido_materno       VARCHAR(50),
    fecha_nacimiento       DATE NOT NULL,
    genero                 VARCHAR(10) NOT NULL CHECK (genero IN ('Masculino', 'Femenino', 'Otro')),
    email                  VARCHAR(100) NOT NULL,
    telefono               VARCHAR(10),
    cuenta_eliminada       SMALLINT NOT NULL DEFAULT 0,
    recibir_notificaciones SMALLINT NOT NULL DEFAULT 1
);
-- El correo es único sin distinguir mayúsculas (como en MySQL con collation _ci).
CREATE UNIQUE INDEX unq_pacientes_email ON pacientes (LOWER(email));

CREATE TABLE pacientes_credenciales (
    id_paciente       INTEGER PRIMARY KEY REFERENCES pacientes (id_paciente) ON DELETE CASCADE,
    password_hash     VARCHAR(255) NOT NULL,
    cuenta_verificada SMALLINT NOT NULL DEFAULT 0
);

CREATE TABLE usuarios (
    id_usuario    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario       VARCHAR(50) NOT NULL,
    nombre        VARCHAR(100) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    rol           VARCHAR(10) NOT NULL DEFAULT 'admin' CHECK (rol IN ('admin', 'recepcion', 'doctor')),
    -- Solo para el rol doctor: médico al que pertenece la cuenta.
    id_doctor     INTEGER UNIQUE REFERENCES doctores (id_doctor) ON DELETE CASCADE
);
CREATE UNIQUE INDEX unq_usuarios_usuario ON usuarios (LOWER(usuario));

CREATE TABLE citas (
    id_cita              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_paciente          INTEGER NOT NULL REFERENCES pacientes (id_paciente) ON DELETE CASCADE,
    id_doctor            INTEGER NOT NULL REFERENCES doctores (id_doctor) ON DELETE CASCADE,
    id_consultorio       INTEGER NOT NULL REFERENCES consultorios (id_consultorio) ON DELETE CASCADE,
    fecha_cita           DATE NOT NULL,
    hora_inicio          TIME NOT NULL,
    motivo_consulta      TEXT NOT NULL,
    estado_cita          VARCHAR(12) NOT NULL DEFAULT 'Pendiente'
                         CHECK (estado_cita IN ('Pendiente', 'Confirmada', 'En Curso', 'Completada', 'Cancelada')),
    oculto_para_paciente SMALLINT NOT NULL DEFAULT 0
);
-- Un solo turno activo por médico, fecha y hora (las citas canceladas no cuentan).
CREATE UNIQUE INDEX unq_citas_horario_activo ON citas (id_doctor, fecha_cita, hora_inicio) WHERE estado_cita <> 'Cancelada';
CREATE INDEX idx_citas_paciente ON citas (id_paciente);
CREATE INDEX idx_citas_fecha ON citas (fecha_cita);

CREATE TABLE bitacora (
    id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario INTEGER,
    rol        VARCHAR(50) NOT NULL,
    accion     VARCHAR(100) NOT NULL,
    entidad    VARCHAR(50) NOT NULL,
    id_entidad INTEGER NOT NULL,
    detalle    TEXT,
    fecha      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_bitacora_fecha ON bitacora (fecha);
CREATE INDEX idx_bitacora_accion ON bitacora (accion);
CREATE INDEX idx_bitacora_usuario ON bitacora (id_usuario);

CREATE TABLE login_attempts (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    identificador VARCHAR(100) NOT NULL,
    attempts      INTEGER NOT NULL DEFAULT 1,
    first_attempt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    block_count   INTEGER NOT NULL DEFAULT 0,
    blocked_until TIMESTAMP
);
CREATE INDEX idx_login_attempts_identificador ON login_attempts (identificador);

CREATE TABLE password_resets (
    id_reset INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email    VARCHAR(100) NOT NULL,
    token    VARCHAR(255) NOT NULL,
    expira   TIMESTAMP NOT NULL,
    usado    SMALLINT NOT NULL DEFAULT 0
);
CREATE INDEX idx_password_resets_email ON password_resets (email);
CREATE INDEX idx_password_resets_token ON password_resets (token);

CREATE TABLE cambios_password_pendientes (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_paciente INTEGER NOT NULL REFERENCES pacientes (id_paciente) ON DELETE CASCADE,
    nuevo_hash  VARCHAR(255) NOT NULL,
    token       VARCHAR(64) NOT NULL UNIQUE,
    expira      TIMESTAMP NOT NULL,
    usado       SMALLINT NOT NULL DEFAULT 0,
    creado_en   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_cambios_password_paciente ON cambios_password_pendientes (id_paciente);

-- Sesiones de PHP (solo se usa con SESSION_DRIVER=database, por ejemplo en Vercel).
CREATE TABLE sesiones (
    id          VARCHAR(128) PRIMARY KEY,
    datos       TEXT NOT NULL,
    actualizado INTEGER NOT NULL
);
CREATE INDEX idx_sesiones_actualizado ON sesiones (actualizado);

-- Recetas, tratamientos con sus tomas y suscripciones a notificaciones push.
CREATE TABLE recetas (
    id_receta     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_paciente   INTEGER NOT NULL REFERENCES pacientes (id_paciente) ON DELETE CASCADE,
    id_doctor     INTEGER NOT NULL REFERENCES doctores (id_doctor) ON DELETE CASCADE,
    id_cita       INTEGER REFERENCES citas (id_cita) ON DELETE SET NULL,
    diagnostico   VARCHAR(255) NOT NULL,
    indicaciones  TEXT,
    fecha_emision TIMESTAMP NOT NULL
);
CREATE INDEX idx_recetas_paciente ON recetas (id_paciente, fecha_emision);
CREATE INDEX idx_recetas_doctor ON recetas (id_doctor, fecha_emision);

CREATE TABLE tratamientos (
    id_tratamiento   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_paciente      INTEGER NOT NULL REFERENCES pacientes (id_paciente) ON DELETE CASCADE,
    id_receta        INTEGER REFERENCES recetas (id_receta) ON DELETE CASCADE,
    origen           VARCHAR(10) NOT NULL CHECK (origen IN ('doctor', 'paciente')),
    medicamento      VARCHAR(120) NOT NULL,
    dosis            VARCHAR(120) NOT NULL,
    frecuencia_horas SMALLINT NOT NULL,
    duracion_dias    SMALLINT NOT NULL,
    fecha_inicio     TIMESTAMP NOT NULL,
    fecha_fin        TIMESTAMP NOT NULL,
    notas            VARCHAR(255),
    estado           VARCHAR(10) NOT NULL DEFAULT 'Activo' CHECK (estado IN ('Activo', 'Pausado', 'Cancelado')),
    creado_en        TIMESTAMP NOT NULL
);
CREATE INDEX idx_tratamientos_paciente ON tratamientos (id_paciente, estado);
CREATE INDEX idx_tratamientos_receta ON tratamientos (id_receta);

CREATE TABLE tomas (
    id_toma        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tratamiento INTEGER NOT NULL REFERENCES tratamientos (id_tratamiento) ON DELETE CASCADE,
    programada_en  TIMESTAMP NOT NULL,
    estado         VARCHAR(10) NOT NULL DEFAULT 'Pendiente' CHECK (estado IN ('Pendiente', 'Tomada', 'Omitida')),
    registrada_en  TIMESTAMP,
    notificada_en  TIMESTAMP,
    UNIQUE (id_tratamiento, programada_en)
);
CREATE INDEX idx_tomas_aviso ON tomas (programada_en, notificada_en);

CREATE TABLE suscripciones_push (
    id_suscripcion INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_paciente    INTEGER NOT NULL REFERENCES pacientes (id_paciente) ON DELETE CASCADE,
    endpoint       TEXT NOT NULL,
    endpoint_hash  CHAR(64) NOT NULL UNIQUE,
    clave_p256dh   VARCHAR(255) NOT NULL,
    clave_auth     VARCHAR(100) NOT NULL,
    agente         VARCHAR(255),
    creada_en      TIMESTAMP NOT NULL,
    ultimo_envio   TIMESTAMP
);
CREATE INDEX idx_suscripciones_paciente ON suscripciones_push (id_paciente);
